% VARIANT TO TEST: no r_I; both pools of a stage feed the next stage together
%
% Block 0 (adapter), unchanged:  EV signal --> ... --> UMP = m_in
% Differentiator 1:
%   m_in --r_S--> m_S --r_Sr--> products        (slow pool)
%   m_in --r_F--> m_F --r_Fr--> products        (fast pool)
%   NO r_I. Instead the two pools are consumed TOGETHER by the two source
%   reactions of differentiator 2:
%   m_F + m_S --r_F_2--> m_F2        m_F + m_S --r_S_2--> m_S2
% Differentiator 2:
%   m_F2 --r_Fr_2--> products  (fast pool)     m_S2 --r_Sr_2--> products  (slow pool)
%   NO r_I_2. The two pools are consumed TOGETHER by the counter reactions:
%   m_F2 + m_S2 --r_c--> m_c         m_F2 + m_S2 + m_I --r_I2--> products
% Counter:
%   m_c + m_I --r_I1--> products (reset);  m_I is refilled towards m_I_base.
% Workbook rows: r_c = r_Cp, r_I1 = r_Cg, r_I2 = r_Cr. The rows r_I and r_I_2 are not used.
%
% What one stage hands to the next is therefore a FLUX (the rate of the
% two-substrate reactions), not a concentration. Section 8 and the last
% figures compare those fluxes with the input level and with its slope.
%
% Units: concentrations and Km in mM, V in mM/s, kcat and k in 1/s, time in s.
% Rates are Michaelis-Menten (two-substrate rates: product of the two
% saturation terms); explicit Euler, one step per input sample. Only the
% analysed distance (row) is simulated; it starts at the design rest state.
%
% Needs Parameters.m, Dataset_cell2cell.mat and kinetics_BRENDA.xlsx.
clc;
% clearvars;
close all;

addingPathParentFolderByName('code'); %[output:25cc651f]
Parameters                               % provides dt0 and fontsize
%%
%[text] ## 1. Input data
% load Dataset_cell2cell.mat
Dataset  = rmmissing(Dataset);
dist     = table2array(Dataset(:,1));
vesicles = table2array(Dataset(:,2:end));

row = 1;                                 % distance analysed in detail
N = size(vesicles,2);
t = (0:N-1)'*dt0;
assert(N >= 3 && all(isfinite(vesicles(row,:))) && all(vesicles(row,:) >= 0) && vesicles(row,1) > 0, ...
    'Use a finite nonnegative EV signal with a positive first sample.');
%%
%[text] ## 2. Enzyme constants from the BRENDA workbook
% Sheet "values" of kinetics_BRENDA.xlsx: reaction label in column B, and the
% columns K_M [mM], SA [umol/min/mg] and MW [mg/umol] found by their titles.
% kcat [1/s] = SA*MW/60.
raw = readcell('kinetics_BRENDA.xlsx','Sheet','values');
isText = @(x) ischar(x) || (isstring(x) && isscalar(x) && ~ismissing(x));
hdrRow = find(any(cellfun(@(x) isText(x) && startsWith(string(x),"K_M"),raw),2),1);
assert(~isempty(hdrRow),'Header row (a cell starting with "K_M") not found in the workbook.');
colOf = @(title) find(cellfun(@(x) isText(x) && startsWith(string(x),title),raw(hdrRow,:)),1);
colKM = colOf("K_M");  colSA = colOf("SA");  colMW = colOf("MW");

reactionNames = {'r_S','r_Sr','r_F','r_Fr','r_I'};

KM = nan(1,5);  kcat = nan(1,5);
for i = 1:5
    r = find(cellfun(@(x) isText(x) && strcmp(strtrim(char(x)),reactionNames{i}),raw(:,2)),1);
    assert(~isempty(r),'Reaction %s not found in column B of the workbook.',reactionNames{i});
    KM(i)   = raw{r,colKM};
    kcat(i) = raw{r,colSA}*raw{r,colMW}/60;
end
assert(all(isfinite([KM kcat])) && all([KM kcat] > 0),'K_M, SA and MW of the five reactions must be positive numbers.');

KM_S  = KM(1);  kcat_S  = kcat(1);       % r_S :  m_in -> m_S
KM_Sr = KM(2);  kcat_Sr = kcat(2);       % r_Sr:  m_S  -> products
KM_F  = KM(3);  kcat_F  = kcat(3);       % r_F :  m_in -> m_F
KM_Fr = KM(4);  kcat_Fr = kcat(4);       % r_Fr:  m_F  -> products
%                                          (row r_I is read but not used in this variant)

reactionNames2 = {'r_S_2','r_Sr_2','r_F_2','r_Fr_2'};
KM2 = nan(1,4);  kcat2 = nan(1,4);
for i = 1:4
    r = find(cellfun(@(x) isText(x) && strcmp(strtrim(char(x)),reactionNames2{i}),raw(:,2)),1);
    assert(~isempty(r),'Reaction %s not found in column B of the workbook.',reactionNames2{i});
    KM2(i)   = raw{r,colKM};
    kcat2(i) = raw{r,colSA}*raw{r,colMW}/60;
end
KM_S_2  = KM2(1);  kcat_S_2  = kcat2(1);   % r_S_2 : m_F + m_S -> m_S2   (K_M used for BOTH substrates: assumed)
KM_Sr_2 = KM2(2);  kcat_Sr_2 = kcat2(2);   % r_Sr_2: m_S2 -> products
KM_F_2  = KM2(3);  kcat_F_2  = kcat2(3);   % r_F_2 : m_F + m_S -> m_F2   (K_M used for BOTH substrates: assumed)
KM_Fr_2 = KM2(4);  kcat_Fr_2 = kcat2(4);   % r_Fr_2: m_F2 -> products

reactionNamesC = {'r_Cp','r_Cg','r_Cr'};
KMC = nan(1,3);  kcatC = nan(1,3);
for i = 1:3
    r = find(cellfun(@(x) isText(x) && strcmp(strtrim(char(x)),reactionNamesC{i}),raw(:,2)),1);
    assert(~isempty(r),'Reaction %s not found in column B of the workbook.',reactionNamesC{i});
    KMC(i)   = raw{r,colKM};
    kcatC(i) = raw{r,colSA}*raw{r,colMW}/60;
end
assert(all(isfinite([KM2 kcat2 KMC kcatC])) && all([KM2 kcat2 KMC kcatC] > 0),'K_M, SA and MW must be positive numbers.');
KM_Cp   = KMC(1);  kcat_Cp = kcatC(1);   % r_c  = r_Cp: m_F2 + m_S2 -> m_c       (K_M for both: assumed)
KM_Cg_c = KMC(2);  kcat_Cg = kcatC(2);   % r_I1 = r_Cg: m_c + m_I -> products;   K_M for m_c
KM_Cg_I = KMC(2);                        %               K_M for m_I: assumed equal
KM_Cr   = KMC(3);  kcat_Cr = kcatC(3);   % r_I2 = r_Cr: m_F2 + m_S2 + m_I -> products (K_M for all three: assumed)
%%
%[text] ## 3. Design choices
Delta_t = 30;                            % relative delay slow - fast pool of differentiator 1 [s]
W_X     = 1/600;                         % input bandwidth [rad/s]
E_max   = 0.02;                          % largest feasible enzyme concentration [mM] (20 uM); only warns here
w_S = 1;  w_F = 1;                       % branch gains
p_F = 1;                                 % folding probability
k_I_fast = 0;                            % (kept for Algorithm 1)

couple_1  = 0.95;                         % share of the slow-branch flux of D1 that leaves through r_F_2 + r_S_2
%                                          at rest; the rest leaves through r_Sr
share_F_2 = 0.5;                         % share of that coupling flux that makes m_F2 (the rest makes m_S2)
tau_F2    = 30;                          % removal time of m_F2 by r_Fr_2 [s]
tau_S2    = 60;                          % removal time of m_S2 by r_Sr_2 [s]
couple_2  = 0.5;                         % share of the smaller D2 input flux that leaves through r_c + r_I2
share_c   = 0.5;                         % share of that coupling flux that makes m_c (the rest is r_I2)
tau_reset    = 600;                      % time constant of the reset of m_c by r_I1 [s]
m_I_base     = 2;                        % buffered level of m_I [mM] (illustrative)
tau_I_supply = 60;                       % refill time of m_I towards m_I_base [s]
assert(all([couple_1 share_F_2 couple_2 share_c] > 0 & [couple_1 share_F_2 couple_2 share_c] < 1),'The four shares must lie between 0 and 1.');
%%
%[text] ## 4. Algorithm 1: enzyme concentrations of r\_S, r\_Sr, r\_F and r\_Fr
% Every rate constant is k = p_F*[E]*kcat/KM, so tau = 1/k_r and w = k_f/k_r.
tau_S_max = 0.1/W_X;                     % "W_X*tau_S << 1" taken as W_X*tau_S <= 0.1
tau_S = 2*Delta_t;                       % line 1: starting value, tau_S > Delta_t
feasible = false;
for iteration = 1:1000                   % lines 2-11: repeat ... until feasible
    alpha = 1-Delta_t/tau_S;                              % line 3
    tau_F = alpha*tau_S;
    E_Sr  = KM_Sr/(p_F*kcat_Sr*tau_S);                    % line 4: slow-branch removal
    k_Fr  = max(1/tau_F-k_I_fast,0);                      % line 5: fast pool removed by r_Fr and r_I
    E_Fr  = KM_Fr*k_Fr/(p_F*kcat_Fr);                     % line 6: fast-branch removal
    E_S   = w_S*KM_S/(p_F*kcat_S*tau_S);                  % line 7: k_f = w*k_r
    E_F   = w_F*KM_F/(p_F*kcat_F*tau_F);
    if all([E_S E_Sr E_F E_Fr] <= E_max)                  % line 8
        feasible = true;
        break
    end
    if tau_S < tau_S_max                                  % line 9: increase tau_S ...
        tau_S = min(1.1*tau_S,tau_S_max);
    elseif Delta_t > 1e-3*tau_S                           %         ... or reduce Delta_t
        Delta_t = 0.9*Delta_t;
    else
        break
    end
end
if ~feasible
    warning('Algorithm 1 found no set below E_max = %.3g uM; using the closest one.',1e3*E_max);
end
fprintf('Algorithm 1: tau_S = %.3g s, tau_F = %.3g s, Delta_t = %.3g s, alpha = %.3g, W_X*tau_S = %.3g\n', ... %[output:group:7e4cda9c] %[output:3601a6fe]
    tau_S,tau_F,Delta_t,alpha,W_X*tau_S); %[output:group:7e4cda9c] %[output:3601a6fe]

V_S  = kcat_S*E_S;
V_Sr = kcat_Sr*E_Sr;
V_F  = kcat_F*E_F;
V_Fr = kcat_Fr*E_Fr;
%%
%[text] ## 5. Rest state and enzyme concentrations of the coupling reactions
m_in_target = min(KM_S,KM_F)/10;
j_S_ref = V_S*m_in_target/(KM_S+m_in_target);            % flux into m_S
j_F_ref = V_F*m_in_target/(KM_F+m_in_target);            % flux into m_F

% ---- Differentiator 1: pools at rest ----
J12 = couple_1*min(j_S_ref,j_F_ref);                     % flux handed to differentiator 2
assert(j_S_ref-J12 < V_Sr && j_F_ref-J12 < V_Fr,'r_Sr or r_Fr is too small for its resting flux.');
m_S_ref = KM_Sr*(j_S_ref-J12)/(V_Sr-(j_S_ref-J12));
m_F_ref = KM_Fr*(j_F_ref-J12)/(V_Fr-(j_F_ref-J12));
pair_F_2 = (m_F_ref/(KM_F_2+m_F_ref))*(m_S_ref/(KM_F_2+m_S_ref));   % two-substrate saturation of r_F_2
pair_S_2 = (m_F_ref/(KM_S_2+m_F_ref))*(m_S_ref/(KM_S_2+m_S_ref));   % ... of r_S_2
J_F2 = share_F_2*J12;      J_S2 = (1-share_F_2)*J12;                 % fluxes into m_F2 and m_S2
E_F_2 = J_F2/(pair_F_2*kcat_F_2);   V_F_2 = kcat_F_2*E_F_2;
E_S_2 = J_S2/(pair_S_2*kcat_S_2);   V_S_2 = kcat_S_2*E_S_2;

% ---- Differentiator 2: removal reactions and pools at rest ----
E_Fr_2 = KM_Fr_2/(tau_F2*kcat_Fr_2);   V_Fr_2 = kcat_Fr_2*E_Fr_2;
E_Sr_2 = KM_Sr_2/(tau_S2*kcat_Sr_2);   V_Sr_2 = kcat_Sr_2*E_Sr_2;
J2c = couple_2*min(J_F2,J_S2);                           % flux handed to the counter
assert(J_F2-J2c < V_Fr_2 && J_S2-J2c < V_Sr_2,'r_Fr_2 or r_Sr_2 is too small for its resting flux.');
m_F2_ref = KM_Fr_2*(J_F2-J2c)/(V_Fr_2-(J_F2-J2c));
m_S2_ref = KM_Sr_2*(J_S2-J2c)/(V_Sr_2-(J_S2-J2c));

% ---- Counter ----
J_c  = share_c*J2c;        J_I2 = (1-share_c)*J2c;       % production of m_c, and r_I2
k_I_supply = 1/tau_I_supply;
m_I_ref = m_I_base-(J_c+J_I2)/k_I_supply;                % at rest r_I1 carries J_c and r_I2 carries J_I2
assert(m_I_ref > 0,'The counter draws more m_I than the supply provides.');
pair_c  = (m_F2_ref/(KM_Cp+m_F2_ref))*(m_S2_ref/(KM_Cp+m_S2_ref));
pair_I2 = (m_F2_ref/(KM_Cr+m_F2_ref))*(m_S2_ref/(KM_Cr+m_S2_ref))*(m_I_ref/(KM_Cr+m_I_ref));
E_Cp = J_c/(pair_c*kcat_Cp);     V_Cp = kcat_Cp*E_Cp;
E_Cr = J_I2/(pair_I2*kcat_Cr);   V_Cr = kcat_Cr*E_Cr;
E_Cg = KM_Cg_c/(tau_reset*kcat_Cg*(m_I_ref/(KM_Cg_I+m_I_ref)));   V_Cg = kcat_Cg*E_Cg;
assert(J_c < V_Cg*m_I_ref/(KM_Cg_I+m_I_ref),'r_I1 cannot remove the resting production of m_c.');
m_c_ref = KM_Cg_c*J_c/(V_Cg*m_I_ref/(KM_Cg_I+m_I_ref)-J_c);

names_all = {'r_S';'r_Sr';'r_F';'r_Fr';'r_F_2';'r_S_2';'r_Fr_2';'r_Sr_2';'r_c = r_Cp';'r_I1 = r_Cg';'r_I2 = r_Cr'};
E_all     = [E_S;E_Sr;E_F;E_Fr;E_F_2;E_S_2;E_Fr_2;E_Sr_2;E_Cp;E_Cg;E_Cr];
kcat_all  = [kcat_S;kcat_Sr;kcat_F;kcat_Fr;kcat_F_2;kcat_S_2;kcat_Fr_2;kcat_Sr_2;kcat_Cp;kcat_Cg;kcat_Cr];
KM_all    = [KM_S;KM_Sr;KM_F;KM_Fr;KM_F_2;KM_S_2;KM_Fr_2;KM_Sr_2;KM_Cp;KM_Cg_c;KM_Cr];
reaction_parameters = table(names_all,KM_all,kcat_all,1e3*E_all,kcat_all.*E_all, ...
    'VariableNames',{'Reaction','Km_mM','kcat_per_s','Enzyme_uM','Vmax_mM_per_s'});
disp(reaction_parameters); %[output:7969a430]
over = find(E_all > E_max);
for i = over.' %[output:group:6f9a01a5]
    warning('%s needs %.3g uM, above the limit of %.3g uM.',names_all{i},1e3*E_all(i),1e3*E_max); %[output:6f53001a] %[output:609224f0] %[output:06820300] %[output:584ec935]
end %[output:group:6f9a01a5]
fprintf('Rest pools [mM]: m_S %.3g, m_F %.3g, m_F2 %.3g, m_S2 %.3g, m_c %.3g, m_I %.4g\n', ... %[output:group:8284c5a1] %[output:1d4edbfd]
    m_S_ref,m_F_ref,m_F2_ref,m_S2_ref,m_c_ref,m_I_ref); %[output:group:8284c5a1] %[output:1d4edbfd]
fprintf('Rest fluxes [mM/s]: into m_S %.3g, into m_F %.3g, D1->D2 %.3g, D2->counter %.3g\n',j_S_ref,j_F_ref,J12,J2c); %[output:512bd503]
%%
%[text] ## 6. Block 0: design concentrations, buffered cosubstrates and capacities
%[text] Concentration targets \[mM\] and turnover numbers are illustrative, not measurements.
tau_B0   = 30;                                   % response time of each Block 0 pool [s]
pool_ref = (j_S_ref+j_F_ref)*tau_B0/1.1;         % reference concentration that gives tau_B0
cAMP_ref = pool_ref; AMP_ref = pool_ref; adn_ref = pool_ref; r1p_ref = pool_ref; uri_ref = pool_ref;
K_EV_AC = 10*vesicles(row,1);            % activation constant in DATASET EV units, not mM
m_ATP_B0 = 2; m_Pi_B0 = 1; m_uracil_B0 = 0.05; m_dUTP_B0 = 0.05;
Km_ADNCYC_ATP = 0.2;
Km_PDE1_cAMP = 10*cAMP_ref;
Km_NTD7_AMP = 10*AMP_ref;
Km_PUNP1_adn = 10*adn_ref;    Km_PUNP1_Pi = 0.1;
Km_PYNP2r_r1p = 10*r1p_ref;   Km_PYNP2r_uracil = 0.005;
Km_r1156_uri = 10*uri_ref;    Km_r1156_dUTP = 0.005;
kcat_ADNCYC = 100; kcat_PDE1 = 100; kcat_NTD7 = 100;
kcat_PUNP1 = 100; kcat_PYNP2r = 100; kcat_r1156 = 100;

% Buffered cosubstrates enter as constant saturation fractions.
ATP_fraction    = m_ATP_B0/(Km_ADNCYC_ATP+m_ATP_B0);
Pi_fraction     = m_Pi_B0/(Km_PUNP1_Pi+m_Pi_B0);
uracil_fraction = m_uracil_B0/(Km_PYNP2r_uracil+m_uracil_B0);
dUTP_fraction   = m_dUTP_B0/(Km_r1156_dUTP+m_dUTP_B0);

% The supply of UMP equals what r_S and r_F withdraw at m_in_target.
J_B0_ref = j_S_ref+j_F_ref;
EV_activity_ref = vesicles(row,1)/(K_EV_AC+vesicles(row,1));
V_ADNCYC = J_B0_ref/(EV_activity_ref*ATP_fraction);
V_PDE1   = J_B0_ref/(cAMP_ref/(Km_PDE1_cAMP+cAMP_ref));
V_NTD7   = J_B0_ref/(AMP_ref/(Km_NTD7_AMP+AMP_ref));
V_PUNP1  = J_B0_ref/((adn_ref/(Km_PUNP1_adn+adn_ref))*Pi_fraction);
V_PYNP2r = J_B0_ref/((r1p_ref/(Km_PYNP2r_r1p+r1p_ref))*uracil_fraction);
V_r1156  = J_B0_ref/((uri_ref/(Km_r1156_uri+uri_ref))*dUTP_fraction);

block0_parameters = table( ...
    {'ADNCYC (assumed EV control)';'PDE1';'NTD7';'PUNP1';'PYNP2r (reverse)';'r1156'}, ...
    [Km_ADNCYC_ATP;Km_PDE1_cAMP;Km_NTD7_AMP;Km_PUNP1_adn;Km_PYNP2r_r1p;Km_r1156_uri], ...
    [kcat_ADNCYC;kcat_PDE1;kcat_NTD7;kcat_PUNP1;kcat_PYNP2r;kcat_r1156], ...
    1e3*[V_ADNCYC/kcat_ADNCYC;V_PDE1/kcat_PDE1;V_NTD7/kcat_NTD7; ...
         V_PUNP1/kcat_PUNP1;V_PYNP2r/kcat_PYNP2r;V_r1156/kcat_r1156], ...
    [V_ADNCYC;V_PDE1;V_NTD7;V_PUNP1;V_PYNP2r;V_r1156], ...
    'VariableNames',{'Reaction','Km_mM','kcat_per_s','Enzyme_uM','Vmax_mM_per_s'});
disp(block0_parameters); %[output:19a895ba]
%%
%[text] ## 7. Simulation (analysed distance), explicit Euler from the rest state
EV = vesicles(row,:).';
m_cAMP = cAMP_ref*ones(N,1); m_AMP = AMP_ref*ones(N,1); m_adn = adn_ref*ones(N,1);
m_r1p = r1p_ref*ones(N,1);   m_uri = uri_ref*ones(N,1); m_in = m_in_target*ones(N,1);
m_S = m_S_ref*ones(N,1);     m_F = m_F_ref*ones(N,1);
m_F2 = m_F2_ref*ones(N,1);   m_S2 = m_S2_ref*ones(N,1);
m_c = m_c_ref*ones(N,1);     m_I = m_I_ref*ones(N,1);
flux_12 = zeros(N,1);        flux_2c = zeros(N,1);       v_c = zeros(N,1);
c = 1;                                                   % (single trace)

for n = 1:N
    % Block 0
    v_ADNCYC = V_ADNCYC*EV(n)/(K_EV_AC+EV(n))*ATP_fraction;              % ATP -> cAMP
    v_PDE1   = V_PDE1*m_cAMP(n)/(Km_PDE1_cAMP+m_cAMP(n));            % cAMP -> AMP
    v_NTD7   = V_NTD7*m_AMP(n)/(Km_NTD7_AMP+m_AMP(n));               % AMP -> adenosine
    v_PUNP1  = V_PUNP1*m_adn(n)/(Km_PUNP1_adn+m_adn(n))*Pi_fraction;     % adenosine -> ribose-1-P
    v_PYNP2r = V_PYNP2r*m_r1p(n)/(Km_PYNP2r_r1p+m_r1p(n))*uracil_fraction;   % ribose-1-P -> uridine
    v_r1156 = V_r1156*m_uri(n)/(Km_r1156_uri+m_uri(n))*dUTP_fraction;   % uridine -> UMP

    % Differentiator 1: two pools, each with its own removal
    v_S  = V_S*m_in(n)/(KM_S+m_in(n));                                   % m_in -> m_S
    v_F  = V_F*m_in(n)/(KM_F+m_in(n));                                   % m_in -> m_F
    v_Sr = V_Sr*m_S(n)/(KM_Sr+m_S(n));                                   % m_S  -> products
    v_Fr = V_Fr*m_F(n)/(KM_Fr+m_F(n));                                   % m_F  -> products

    % Coupling D1 -> D2: both pools are consumed together
    v_F_2 = V_F_2*m_F(n)/(KM_F_2+m_F(n))*m_S(n)/(KM_F_2+m_S(n));         % m_F + m_S -> m_F2
    v_S_2 = V_S_2*m_F(n)/(KM_S_2+m_F(n))*m_S(n)/(KM_S_2+m_S(n));         % m_F + m_S -> m_S2
    flux_12(n) = v_F_2+v_S_2;

    % Differentiator 2: two pools, each with its own removal
    v_Fr_2 = V_Fr_2*m_F2(n)/(KM_Fr_2+m_F2(n));                           % m_F2 -> products
    v_Sr_2 = V_Sr_2*m_S2(n)/(KM_Sr_2+m_S2(n));                           % m_S2 -> products

    % Coupling D2 -> counter: both pools are consumed together
    v_c(n) = V_Cp*m_F2(n)/(KM_Cp+m_F2(n))*m_S2(n)/(KM_Cp+m_S2(n));       % m_F2 + m_S2 -> m_c
    v_I2   = V_Cr*m_F2(n)/(KM_Cr+m_F2(n))*m_S2(n)/(KM_Cr+m_S2(n))*m_I(n)/(KM_Cr+m_I(n));   % m_F2 + m_S2 + m_I -> products
    flux_2c(n) = v_c(n)+v_I2;

    % Counter
    v_I1 = V_Cg*m_c(n)/(KM_Cg_c+m_c(n))*m_I(n)/(KM_Cg_I+m_I(n));         % m_c + m_I -> products
    if n == N, break; end

    dt = t(n+1)-t(n);
    m_cAMP(n+1) = m_cAMP(n)+dt*(v_ADNCYC-v_PDE1);
    m_AMP(n+1)  = m_AMP(n) +dt*(v_PDE1-v_NTD7);
    m_adn(n+1)  = m_adn(n) +dt*(v_NTD7-v_PUNP1);
    m_r1p(n+1)  = m_r1p(n) +dt*(v_PUNP1-v_PYNP2r);
    m_uri(n+1)  = m_uri(n) +dt*(v_PYNP2r-v_r1156);
    m_in(n+1)   = m_in(n)  +dt*(v_r1156-v_S-v_F);
    m_S(n+1)    = m_S(n)   +dt*(v_S-v_Sr-flux_12(n));
    m_F(n+1)    = m_F(n)   +dt*(v_F-v_Fr-flux_12(n));
    m_F2(n+1)   = m_F2(n)  +dt*(v_F_2-v_Fr_2-flux_2c(n));
    m_S2(n+1)   = m_S2(n)  +dt*(v_S_2-v_Sr_2-flux_2c(n));
    m_c(n+1)    = m_c(n)   +dt*(v_c(n)-v_I1);
    m_I(n+1)    = m_I(n)   +dt*(k_I_supply*(m_I_base-m_I(n))-v_I1-v_I2);
    pools = [m_cAMP(n+1),m_AMP(n+1),m_adn(n+1),m_r1p(n+1),m_uri(n+1),m_in(n+1), ...
             m_S(n+1),m_F(n+1),m_F2(n+1),m_S2(n+1),m_c(n+1),m_I(n+1)];
    assert(all(isfinite(pools)) && all(pools >= 0),'Invalid Euler step at n = %d; reduce dt0.',n);
end
%%
%[text] ## 8. Does anything in the chain follow the slope of the input?
% Everything is shown relative to its value at rest. A differentiator output
% would leave 1 while m_in changes quickly and come back to 1 afterwards. A
% signal that follows the input LEVEL stays away from 1 as long as m_in does.
negativeSlope = -gradient(m_in,t);
rel = @(x) x/x(1);
iShow = unique(round(linspace(1,N,9)));
fprintf('\n%9s %9s %11s %11s %9s %9s %9s\n','time[min]','m_in','flux D1>D2','flux D2>C','m_F2','m_S2','m_c'); %[output:4753f81a]
for k = iShow %[output:group:472d2fcb]
    fprintf('%9.1f %9.4f %11.4f %11.4f %9.4f %9.4f %9.4f\n',t(k)/60,m_in(k)/m_in(1),flux_12(k)/flux_12(1), ... %[output:9bd57789]
        flux_2c(k)/flux_2c(1),m_F2(k)/m_F2(1),m_S2(k)/m_S2(1),m_c(k)/m_c(1)); %[output:9bd57789]
end %[output:group:472d2fcb]
cc = corrcoef([m_in,flux_12,flux_2c,m_c]);
fprintf('\nCorrelation with the input LEVEL m_in:  flux D1>D2 %.3f, flux D2>counter %.3f, m_c %.3f\n',cc(1,2),cc(1,3),cc(1,4)); %[output:52b41086]
fprintf('Last value relative to rest (1 = came back): m_in %.3f, flux D1>D2 %.3f, flux D2>counter %.3f, m_c %.3f\n', ... %[output:group:75594134] %[output:86ffaaf1]
    m_in(end)/m_in(1),flux_12(end)/flux_12(1),flux_2c(end)/flux_2c(1),m_c(end)/m_c(1)); %[output:group:75594134] %[output:86ffaaf1]
%%
%[text] ## 9. Figures
% 1. Input.
figure; %[output:475363f5]
plot(t/60,m_in,'LineWidth',2); grid on; %[output:475363f5]
xlabel('Time [min]'); ylabel('UMP: m_{in} [mM]'); %[output:475363f5]
legend(sprintf('d = %.3g um',dist(row)*1e6),'Location','southwest'); %[output:475363f5]
set(gca,'FontSize',fontsize+4); %[output:475363f5]

% 2. Pools of the two differentiators.
figure; %[output:64b33d7e]
plot(t/60,[m_S,m_F,m_S2,m_F2],'LineWidth',2); grid on; %[output:64b33d7e]
xlabel('Time [min]'); ylabel('Concentration [mM]'); %[output:64b33d7e]
legend('m_S','m_F','m_{S2}','m_{F2}','Location','best'); %[output:64b33d7e]
xlim([0,min(150,t(end)/60)]); set(gca,'FontSize',fontsize); %[output:64b33d7e]

% 3. What each stage hands on, relative to rest, against the input level and slope.
figure; %[output:9d288d46]
yyaxis left; %[output:9d288d46]
plot(t/60,[rel(m_in),rel(flux_12),rel(flux_2c)],'LineWidth',1.8); ylabel('relative to rest'); %[output:9d288d46]
yyaxis right; %[output:9d288d46]
plot(t/60,negativeSlope,':','LineWidth',1.5); ylabel('-dm_{in}/dt [mM/s]'); %[output:9d288d46]
xlabel('Time [min]'); xlim([0,min(150,t(end)/60)]); grid on; %[output:9d288d46]
legend('m_{in}','flux D1 \rightarrow D2','flux D2 \rightarrow counter','input falling slope','Location','best'); %[output:9d288d46]
set(gca,'FontSize',fontsize); %[output:9d288d46]

% 4. Counter.
figure; %[output:4282603b]
plot(t/60,m_c,'LineWidth',2); grid on; %[output:4282603b]
xlabel('Time [min]'); ylabel('m_c [mM]'); xlim([0,min(150,t(end)/60)]); %[output:4282603b]
set(gca,'FontSize',fontsize+4); %[output:4282603b]
